import glob,json,collections,re
c=collections.Counter(); ex={}
for f in sorted(glob.glob('north-*')):
    b=open(f,'rb').read()
    for l in b.decode('utf-8').split('\n'):
        if not l.strip(): continue
        v=json.loads(l)
        objs=v if isinstance(v,list) else [v]
        c['list' if isinstance(v,list) else 'obj']+=1
